def map_legacy_voucher_data(apps, schema_editor):
    """نگاشت حواله‌های قدیمی به ساختار جدید بدون حذف داده.

    - 'in'  → 'receipt' با انبار مقصد
    - 'out' → 'issue'  با انبار مبدأ
    - حواله‌های قدیمی عملاً نهایی‌شده‌اند → status='finalized'
    - quantity قدیمی قلم‌ها به trade_quantity و base_quantity منتقل می‌شود
      (نرخ تبدیل ثبت‌نشده بود؛ هر دو برابر مقدار قدیمی می‌مانند)
    """
    WarehouseVoucher = apps.get_model('purchases', 'WarehouseVoucher')
    WarehouseVoucherItem = apps.get_model('purchases', 'WarehouseVoucherItem')

    for voucher in WarehouseVoucher.objects.all():
        old_type = voucher.voucher_type
        old_wh_id = voucher.warehouse_id
        if old_type == 'in':
            voucher.voucher_type = 'receipt'
            voucher.destination_warehouse_id = old_wh_id
        elif old_type == 'out':
            voucher.voucher_type = 'issue'
            voucher.source_warehouse_id = old_wh_id
        else:
            continue  # نوع جدید از قبل — دست نزن
        voucher.status = 'finalized'
        voucher.save(update_fields=[
            'voucher_type', 'status',
            'source_warehouse_id', 'destination_warehouse_id',
        ])

    for item in WarehouseVoucherItem.objects.all():
        item.trade_quantity = item.quantity
        item.base_quantity = item.quantity
        item.save(update_fields=['trade_quantity', 'base_quantity'])


